// 1. Вхідні дані: IP з Webhook і повні відповіді обох API
const ip = $('Webhook').first().json.body.ip;
const vtRes = $('VirusTotal').first().json;
const abRes = $('AbuseIPDB').first().json;

// 2. Перекладаємо статус-код у зрозуміле повідомлення
function describeError(service, code) {
  if (code === 200) return null; // усе гаразд, помилки немає
  if (code === 401 || code === 403) return `${service}: помилка автентифікації (${code}), перевірте ключ у Credentials`;
  if (code === 429) return `${service}: вичерпано ліміт запитів (429)`;
  if (code === 400 || code === 422) return `${service}: некоректний запит (${code}), перевірте формат IP`;
  if (code === 404) return `${service}: дані не знайдено (404)`;
  return `${service}: неочікувана відповідь (${code})`;
}

const errors = [
  describeError('VirusTotal', vtRes.statusCode),
  describeError('AbuseIPDB', abRes.statusCode)
].filter(Boolean); // прибираємо null, лишаємо тільки реальні помилки

const vtOk = vtRes.statusCode === 200;
const abOk = abRes.statusCode === 200;

// 3. Беремо дані лише з тих джерел, які відповіли успішно
const vtStats = vtOk ? vtRes.body.data.attributes.last_analysis_stats : {};
const abuse = abOk ? abRes.body.data : {};

const abuseScore = abuse.abuseConfidenceScore ?? 0;
const vtMalicious = vtStats.malicious ?? 0;
const vtSuspicious = vtStats.suspicious ?? 0;

// 4. Пороги
const ABUSE_HIGH = 50;
const VT_HIGH = 3;
const ABUSE_MEDIUM = 20;

// 5. Вердикт
let verdict = 'LOW';
if (abuseScore >= ABUSE_HIGH || vtMalicious >= VT_HIGH) {
  verdict = 'HIGH';
} else if (abuseScore >= ABUSE_MEDIUM || vtMalicious >= 1 || vtSuspicious >= 1) {
  verdict = 'MEDIUM';
}

// 6. Якщо джерела не відповіли, не видаємо оманливий LOW
if (!vtOk && !abOk) {
  verdict = 'UNKNOWN';
} else if (errors.length > 0 && verdict === 'LOW') {
  verdict = 'LOW (неповні дані)';
}

return [{
  json: {
    ip,
    verdict,
    abuse_score: abOk ? `${abuseScore}%` : 'n/a',
    vt_malicious: vtOk ? vtMalicious : 'n/a',
    vt_suspicious: vtOk ? vtSuspicious : 'n/a',
    isp: abuse.isp ?? 'n/a',
    country: abuse.countryCode ?? 'n/a',
    is_tor: abuse.isTor ?? 'n/a',
    is_whitelisted: abuse.isWhitelisted ?? 'n/a',
    errors: errors.length > 0 ? errors.join('; ') : 'none'
  }
}];

// 1. Беремо значення з тіла запиту і прибираємо пробіли по краях
const raw = $input.first().json.body?.ip;
const ip = typeof raw === 'string' ? raw.trim() : '';

// 2. Перевірка формату IPv4: 4 числа від 0 до 255, розділені крапками
const parts = ip.split('.');
const isIPv4 = parts.length === 4 && parts.every(p =>
  /^\d{1,3}$/.test(p) &&          // лише 1-3 цифри
  Number(p) <= 255 &&             // не більше 255
  String(Number(p)) === p         // без провідних нулів ("01")
);

// 3. Приватні та службові діапазони: репутації в них немає,
//    і внутрішні адреси не варто відправляти стороннім сервісам
function isPrivateOrReserved(ip) {
  const [a, b] = ip.split('.').map(Number);
  return a === 0 || a === 10 || a === 127 ||
    (a === 100 && b >= 64 && b <= 127) ||   // CGNAT
    (a === 169 && b === 254) ||             // link-local
    (a === 172 && b >= 16 && b <= 31) ||
    (a === 192 && b === 168) ||
    a >= 224;                                // multicast і зарезервовані
}

// 4. Вирішуємо і пояснюємо причину
let valid = true;
let reason = 'ok';
if (!ip) {
  valid = false; reason = 'поле ip порожнє або відсутнє';
} else if (!isIPv4) {
  valid = false; reason = 'не є коректною IPv4-адресою';
} else if (isPrivateOrReserved(ip)) {
  valid = false; reason = 'приватна або службова адреса, перевірка не потрібна';
}

return [{ json: { ip: ip || String(raw), valid, reason } }];

